def make_result_html(view_imgs: list, skin_img: Image.Image) -> str:
    """캐러셀 미리보기(앞→오른→뒤→왼) + 다운로드 버튼"""
    labels = ["앞", "오른쪽", "뒤", "왼쪽"]
    n = len(view_imgs)

    imgs_b64 = []
    for img in view_imgs:
        buf = io.BytesIO()
        img.save(buf, format="PNG")
        imgs_b64.append(base64.b64encode(buf.getvalue()).decode())

    sb = io.BytesIO()
    skin_img.save(sb, format="PNG")
    skin_b64 = base64.b64encode(sb.getvalue()).decode()

    # 이미지를 숨겨진 span 에 저장 — script 없이 순수 inline onclick으로 접근
    hidden_imgs = "".join(
        f'<span id="sfi{i}" style="display:none">{imgs_b64[i]}</span>'
        for i in range(n)
    )
    # 인디케이터 점
    dots = "".join(
        f'<div id="sfd{i}" style="width:7px;height:7px;border-radius:50%;'
        f'background:{"#00C9A7" if i==0 else "rgba(255,255,255,.3)"};'
        f'transition:background .2s;"></div>'
        for i in range(n)
    )

    # inline onclick — 외부 함수 없이 self-contained
    def nav_onclick(d: int) -> str:
        return (
            "var w=document.getElementById('sfwrap');"
            f"var n=(parseInt(w.dataset.idx||0)+({d})+{n})%{n};"
            "w.dataset.idx=n;"
            "document.getElementById('sfimg').src='data:image/png;base64,'+document.getElementById('sfi'+n).textContent.trim();"
            f"var lb=[{','.join(repr(l) for l in labels[:n])}];"
            "document.getElementById('sflbl').textContent=lb[n];"
            f"for(var i=0;i<{n};i++){{"
            "document.getElementById('sfd'+i).style.background=(i===n?'#00C9A7':'rgba(255,255,255,.3)');}"
        )

    return f"""
  {hidden_imgs}

  <!-- 캐러셀 -->
  <div id="sfwrap" data-idx="0"
       style="position:relative;border-style:solid;border-width:5px;border-color:#b8b8b8 #444 #444 #b8b8b8;border-radius:0;box-shadow:0 0 0 2px #111;background:#181818;overflow:hidden;user-select:none;height:340px;box-sizing:content-box;">

    <!-- 방향 라벨 -->
    <div id="sflbl"
         style="position:absolute;top:10px;left:50%;transform:translateX(-50%);
                background:rgba(0,0,0,.6);color:#00C9A7;font-size:12px;
                font-weight:700;padding:3px 12px;border-radius:20px;z-index:2;
                font-family:sans-serif;white-space:nowrap;">앞</div>

    <!-- 이미지 -->
    <img id="sfimg"
         src="data:image/png;base64,{imgs_b64[0]}"
         style="width:100%;height:340px;object-fit:contain;
                image-rendering:pixelated;display:block;"
         alt="skin preview">

    <!-- 왼쪽 화살표 -->
    <button onclick="{nav_onclick(-1)}"
      style="position:absolute;left:8px;top:50%;transform:translateY(-50%);
             background:rgba(0,0,0,.55);border:1px solid #444;color:#ddd;
             width:36px;height:36px;border-radius:50%;font-size:18px;
             cursor:pointer;z-index:2;line-height:1;padding:0;">&#8592;</button>

    <!-- 오른쪽 화살표 -->
    <button onclick="{nav_onclick(1)}"
      style="position:absolute;right:8px;top:50%;transform:translateY(-50%);
             background:rgba(0,0,0,.55);border:1px solid #444;color:#ddd;
             width:36px;height:36px;border-radius:50%;font-size:18px;
             cursor:pointer;z-index:2;line-height:1;padding:0;">&#8594;</button>

    <!-- 인디케이터 -->
    <div style="position:absolute;bottom:8px;left:50%;transform:translateX(-50%);
                display:flex;gap:6px;z-index:2;">{dots}</div>
  </div>

  <!-- 다운로드 버튼 -->
<div style="margin-top:8px;">
  <a href="data:image/png;base64,{skin_b64}"
     download="skinforge_skin.png"
     style="display:block;text-decoration:none;width:100%;height:48px;line-height:48px;padding:0;background:#868686;border-style:solid;border-width:3px;border-color:#d0d0d0 #3a3a3a #3a3a3a #d0d0d0;border-radius:0;box-shadow:0 0 0 2px #111;color:#fff;font-size:15px;font-weight:700;text-shadow:2px 2px 0 #333;box-sizing:border-box;text-align:center;font-family:Inter,sans-serif;cursor:pointer;"
     onmouseover="this.style.filter='brightness(1.12)'"
     onmouseout="this.style.filter=''">PNG 다운로드</a>
"""


def process(photo: Image.Image):
    if photo is None:
        return _RESULT_EMPTY, "⚠️ 사진을 업로드해 주세요."
    try:
        features = extract_features(photo)
        tone  = features.get("skin_tone", "warm_bright")
        status = (f"✅ 피부톤: {tone} | "
                  f"헤어: {features.get('hair_color')} {features.get('hair_style')} | "
                  f"상의: {features.get('top_style')}")

        skin_img = generate_skin(features)
        skin_img, is_valid, errors = validate_and_fix(skin_img)
        if not is_valid:
            status += f" | ⚠️ {errors}"

        view_imgs = make_2d_preview(skin_img)
        print(f"[skinforge] 생성 완료 | {status}")
        return make_result_html(view_imgs, skin_img), status

    except Exception as e:
        import traceback
        traceback.print_exc()
        err_html = f"""
<div style="background:#111;border-radius:16px;border:1px solid #2a1a1a;
    padding:20px;color:#f66;font-size:13px;">
  ❌ 오류: {e}
</div>"""
        return err_html, f"❌ 오류: {e}"


